import java.util.*;

public class Main {
    public static void main(String[] args) {
        Pipeline pipeline = new Pipeline();
        pipeline.defineStage("build", Collections.emptyList());
        pipeline.defineStage("test", Arrays.asList("build"));
        pipeline.defineStage("lint", Arrays.asList("build"));
        pipeline.defineStage("deploy", Arrays.asList("test", "lint"));

        System.out.println(pipeline.runStage("build", true));   // no dependencies, runs immediately, succeeds
        System.out.println(pipeline.runStage("test", false));   // build succeeded, test becomes eligible, but fails
        System.out.println(pipeline.runStage("lint", true));    // independent of test, also eligible, succeeds normally
        System.out.println(pipeline.runStage("deploy", true));  // depends on test AND lint, test failed, so skipped

        System.out.println("Final statuses: " + pipeline.describe());
    }
}

// A CI/CD pipeline: a stage only actually executes once every one of its
// declared dependencies has succeeded, independent stages are otherwise
// unaffected by each other, and a failed dependency causes a stage to be
// skipped rather than run at all.
class Pipeline {
    enum Status { SUCCESS, FAILED, SKIPPED }

    private final Map<String, List<String>> dependencies = new LinkedHashMap<>();
    private final Map<String, Status> results = new LinkedHashMap<>();

    void defineStage(String stageId, List<String> deps) {
        dependencies.put(stageId, deps);
    }

    String runStage(String stageId, boolean outcomeIfRun) {
        for (String dep : dependencies.get(stageId)) {
            if (results.get(dep) != Status.SUCCESS) {
                results.put(stageId, Status.SKIPPED);
                return stageId + ": SKIPPED (dependency " + dep + " did not succeed)";
            }
        }
        if (outcomeIfRun) {
            results.put(stageId, Status.SUCCESS);
            return stageId + ": SUCCESS";
        } else {
            results.put(stageId, Status.FAILED);
            return stageId + ": FAILED";
        }
    }

    String describe() {
        StringBuilder sb = new StringBuilder();
        for (Map.Entry<String, Status> e : results.entrySet()) {
            sb.append(e.getKey()).append("=").append(e.getValue()).append(" ");
        }
        return sb.toString().trim();
    }
}

