class Pipeline:
    # A CI/CD pipeline: a stage only actually executes once every one of its
    # declared dependencies has succeeded, independent stages are otherwise
    # unaffected by each other, and a failed dependency causes a stage to be
    # skipped rather than run at all.
    def __init__(self):
        self.dependencies = {}  # stageId -> [depIds]
        self.results = {}  # stageId -> "SUCCESS" | "FAILED" | "SKIPPED"

    def define_stage(self, stage_id, deps):
        self.dependencies[stage_id] = deps

    def run_stage(self, stage_id, outcome_if_run):
        for dep in self.dependencies[stage_id]:
            if self.results.get(dep) != "SUCCESS":
                self.results[stage_id] = "SKIPPED"
                return f"{stage_id}: SKIPPED (dependency {dep} did not succeed)"

        if outcome_if_run:
            self.results[stage_id] = "SUCCESS"
            return f"{stage_id}: SUCCESS"
        else:
            self.results[stage_id] = "FAILED"
            return f"{stage_id}: FAILED"

    def describe(self):
        return " ".join(f"{stage_id}={status}" for stage_id, status in self.results.items())


def main():
    pipeline = Pipeline()
    pipeline.define_stage("build", [])
    pipeline.define_stage("test", ["build"])
    pipeline.define_stage("lint", ["build"])
    pipeline.define_stage("deploy", ["test", "lint"])

    print(pipeline.run_stage("build", True))    # no dependencies, runs immediately, succeeds
    print(pipeline.run_stage("test", False))    # build succeeded, test becomes eligible, but fails
    print(pipeline.run_stage("lint", True))     # independent of test, also eligible, succeeds normally
    print(pipeline.run_stage("deploy", True))   # depends on test AND lint, test failed, so skipped

    print("Final statuses:", pipeline.describe())


if __name__ == "__main__":
    main()

