using namespace std;

// A CI/CD pipeline: a stage only actually executes once every one of its
// declared dependencies has succeeded, independent stages are otherwise
// unaffected by each other, and a failed dependency causes a stage to be
// skipped rather than run at all.
class Pipeline {
public:
    void defineStage(const string& stageId, const vector<string>& deps) {
        dependencies[stageId] = deps;
        stageOrder.push_back(stageId);
    }

    string runStage(const string& stageId, bool outcomeIfRun) {
        for (const auto& dep : dependencies[stageId]) {
            if (results.count(dep) == 0 || results[dep] != "SUCCESS") {
                results[stageId] = "SKIPPED";
                return stageId + ": SKIPPED (dependency " + dep + " did not succeed)";
            }
        }

        if (outcomeIfRun) {
            results[stageId] = "SUCCESS";
            return stageId + ": SUCCESS";
        } else {
            results[stageId] = "FAILED";
            return stageId + ": FAILED";
        }
    }

    string describe() {
        string result;
        for (const auto& stageId : stageOrder) {
            result += stageId + "=" + results[stageId] + " ";
        }
        if (!result.empty()) result.pop_back();
        return result;
    }

private:
    map<string, vector<string>> dependencies;
    map<string, string> results;
    vector<string> stageOrder;
};

int main() {
    Pipeline pipeline;
    pipeline.defineStage("build", {});
    pipeline.defineStage("test", {"build"});
    pipeline.defineStage("lint", {"build"});
    pipeline.defineStage("deploy", {"test", "lint"});

    cout << pipeline.runStage("build", true) << endl;   // no dependencies, runs immediately, succeeds
    cout << pipeline.runStage("test", false) << endl;   // build succeeded, test becomes eligible, but fails
    cout << pipeline.runStage("lint", true) << endl;    // independent of test, also eligible, succeeds normally
    cout << pipeline.runStage("deploy", true) << endl;  // depends on test AND lint, test failed, so skipped

    cout << "Final statuses: " << pipeline.describe() << endl;

    return 0;
}

